/* ============================================================
   v6 — 删除交互 / 数据重做 / 拜访详情 / 天气精修 / 土地实时切换
   ============================================================ */

/* ---- 更有质感的树木:柔和落地阴影 + 完成态光晕 + 阶段微差 ---- */
.art-tree img{filter:drop-shadow(0 12px 9px rgba(31,58,40,.34)) saturate(1.05)}
.art-tree.complete img{filter:drop-shadow(0 12px 9px rgba(31,58,40,.34)) saturate(1.05)}
.art-tree.stage-seed{opacity:.9}
.art-tree::after{content:'';position:absolute;left:50%;bottom:2px;transform:translateX(-50%);width:56%;height:12px;border-radius:50%;background:radial-gradient(ellipse,rgba(40,64,44,.28),transparent 72%);z-index:-1}
@keyframes sway{0%,100%{transform:scale(var(--scale)) rotate(-1.1deg)}50%{transform:scale(var(--scale)) rotate(1.1deg)}}
@media(prefers-reduced-motion:no-preference){.grove .art-tree,.detail-scene .art-tree{transform-origin:bottom center;animation:sway 6s ease-in-out infinite}.grove .art-tree:nth-child(2n){animation-duration:7.2s}.grove .art-tree:nth-child(3n){animation-duration:5.4s}}

/* ---- 首页土地:删除按钮 ---- */
.project{position:relative}
.project .project-open{all:unset;cursor:pointer;display:block;width:100%;height:100%;position:absolute;inset:0}
.project .project-open>*{position:relative}
.plot-del{position:absolute;top:12px;right:12px;z-index:6;width:34px;height:34px;border:0;border-radius:12px;background:rgba(255,255,255,.72);color:#9a4b3d;display:grid;place-items:center;backdrop-filter:blur(6px);box-shadow:0 6px 16px rgba(60,40,35,.18);transition:transform .2s,background .2s}
.plot-del:hover{background:#fff;transform:scale(1.08)}
.plot-del svg{width:16px}
.empty-hint{margin:26px 8px;padding:28px 20px;border-radius:22px;background:rgba(255,252,241,.7);text-align:center;font-size:12px;color:#5d7263;backdrop-filter:blur(10px)}
.empty-hint b{color:#2f6146}

/* ---- 子任务:信息区 + 删除按钮 ---- */
.task-list article{position:relative}
.task-info{flex:1;display:grid;min-width:0}
.task-info b{overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.task-del{flex:0 0 auto;width:32px;height:32px;border:0;border-radius:10px;background:transparent;color:#b08072;display:grid;place-items:center;transition:background .2s,color .2s}
.task-del:hover{background:#f7e5df;color:#9a4b3d}
.task-del svg{width:15px}
.grove-empty{color:#5d7263;font-size:11px;align-self:center;text-align:center;padding:0 30px}

/* ---- 确认弹窗 ---- */
.confirm{width:min(100%,480px);margin:auto;padding:28px 24px 24px;background:#f6f2e8;border-radius:26px 26px 0 0;box-shadow:0 -12px 40px rgba(30,50,36,.25)}
.confirm h2{font-size:22px;color:#2c503d}
.confirm p{font-size:12px;line-height:1.7;color:#6a7a6f;margin:10px 0 20px}
.confirm-btns{display:flex;gap:10px}
.confirm-btns button{flex:1;padding:14px;border:0;border-radius:14px;font-size:13px}
.confirm-btns .ghost{background:#e6e0d2;color:#4a5a4f}
.confirm-btns .danger{background:#b5503f;color:#fff}
/* ============ 数据统计页重做 ============ */
.stats-page .lead{font-size:11px;color:#748177;margin:6px 0 18px}
.metrics{display:grid;grid-template-columns:1fr 1fr;gap:10px;margin:6px 0 8px}
.metric{position:relative;display:flex;align-items:center;gap:11px;padding:13px 14px;border-radius:16px;background:linear-gradient(150deg,#fffdf5,#eff0e1);box-shadow:0 6px 16px rgba(48,74,55,.09);border:1px solid #fff}
.metric-ico{width:34px;height:34px;border-radius:11px;background:#e7f0e2;color:#3f7150;display:grid;place-items:center;margin-bottom:0;flex:none}.metric-body{display:flex;flex-direction:column;min-width:0}
.metric-ico svg{width:17px}
.metric strong{font:700 24px 'Noto Serif SC';color:#2d543f;display:block;line-height:1.05}
.metric span{font-size:10.5px;color:#3f5347;font-weight:600;margin-top:3px}
.metric em{display:block;font-style:normal;font-size:9px;color:#8a9990;margin-top:3px}
.sec-title{font-size:17px;color:#2b4c3c;margin:28px 0 12px}
.sec-head{display:flex;justify-content:space-between;align-items:center}
.sec-head .sec-title{margin-bottom:0}

/* 种类分布 */
.type-dist{display:grid;gap:12px;padding:18px;border-radius:20px;background:rgba(255,253,245,.85);box-shadow:0 8px 22px rgba(48,74,55,.1);border:1px solid #fff}
.type-row{display:flex;align-items:center;gap:10px}
.type-dot{width:12px;height:12px;border-radius:50%;flex:0 0 12px}
.type-dot.pine{background:#2f6b4c}.type-dot.poplar{background:#7fa15c}.type-dot.fruit{background:#c9744d}
.type-row b{font-size:12px;width:42px;color:#33513f}
.type-bar{flex:1;height:9px;border-radius:6px;background:#e7e2d3;overflow:hidden}
.type-bar i{display:block;height:100%;border-radius:6px;background:linear-gradient(90deg,#5f9169,#2f6b4c)}
.type-row em{font-style:normal;font-size:11px;color:#6a7a6f;width:40px;text-align:right}

/* 生长情况 */
.stage-dist{display:grid;grid-template-columns:repeat(5,1fr);gap:8px}
.stage-chip{padding:14px 4px;border-radius:16px;background:rgba(255,253,245,.85);text-align:center;box-shadow:0 6px 18px rgba(48,74,55,.09);border:1px solid #fff}
.stage-chip strong{display:block;font:700 22px 'Noto Serif SC';color:#2f6146}
.stage-chip span{font-size:9px;color:#748177}

/* 时间分析柱状图 */
.bucket-switch{display:flex;background:#e6e1d3;border-radius:12px;padding:3px}
.bucket-switch button{border:0;background:none;padding:6px 14px;font-size:12px;color:#6a7a6f;border-radius:9px}
.bucket-switch button.on{background:#fff;color:#2f6146;box-shadow:0 3px 8px rgba(48,74,55,.14)}
.chart-card{margin:12px auto 0;padding:18px 16px 12px;width:92%;border-radius:20px;background:linear-gradient(160deg,rgba(255,253,245,.95),rgba(240,245,235,.92));box-shadow:0 8px 22px rgba(48,74,55,.1);border:1px solid #fff}
.bars{display:flex;align-items:flex-end;gap:8px;height:150px}
.bar-col{flex:1;display:flex;flex-direction:column;align-items:center;gap:6px;height:100%;justify-content:flex-end;min-width:0}
.bar-track{width:100%;max-width:26px;flex:1;display:flex;align-items:flex-end}
.bar-fill{width:100%;min-height:4px;border-radius:8px 8px 3px 3px;background:linear-gradient(180deg,#6fa572,#2f6b4c);position:relative;transition:height .5s cubic-bezier(.2,.8,.2,1)}
.bar-fill i{position:absolute;top:-15px;left:50%;transform:translateX(-50%);font-style:normal;font-size:8px;color:#4a6553;white-space:nowrap}
.bar-col small{font-size:8px;color:#748177;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;max-width:100%}
.bars-empty{padding:34px 10px;text-align:center;font-size:12px;color:#8a9990}

/* ============ 拜访:可点击 + 详情弹层 ============ */
.neighbor-scene{all:unset;cursor:pointer;display:flex;position:relative}
.neighbor-scene .peek{position:absolute;right:12px;bottom:10px;font-size:9px;color:#fff;background:rgba(40,64,44,.5);padding:5px 10px;border-radius:12px;backdrop-filter:blur(4px)}
.nb-actions{display:flex;gap:8px;margin-top:4px}
.nb-view{border:1px solid #cdd8cc;background:#fff;color:#3f6845;border-radius:14px;padding:8px 12px;font-size:10px}
.nb-like{display:inline-flex;align-items:center;gap:5px;border:0;background:#fbedcf;color:#a5772e;border-radius:14px;padding:8px 12px;font-size:10px}
.nb-like svg{width:13px}
.nb-like.liked{background:#f6c95b;color:#5a3e10}
.sheet{align-items:end}
.garden-detail{position:relative;width:min(100%,440px);max-height:86vh;overflow:auto;padding:26px 22px 26px;border-radius:22px;background:linear-gradient(180deg,#fbf7ee,#eef2e6);box-shadow:0 18px 50px rgba(30,50,36,.34)}
.garden-detail small{color:#8a7a58}
.garden-detail h2{font-size:26px;color:#2b4c3c;margin:4px 0}
.garden-detail>p{font-size:12px;color:#6a7a6f;margin-bottom:14px}
.sheet-close{position:absolute;top:16px;right:16px;width:34px;height:34px;border:0;border-radius:50%;background:#eae4d6;color:#5a6a5e;display:grid;place-items:center}
.sheet-close svg{width:16px}
.detail-scene{height:200px;display:flex;align-items:flex-end;justify-content:center;gap:0;border-radius:24px;padding:0 18px 26px;background:linear-gradient(180deg,rgba(244,225,178,.6) 0 38%,rgba(139,181,114,.82) 39% 70%,rgba(77,120,72,.9) 71%);box-shadow:inset 0 -30px 40px rgba(40,79,62,.28);overflow:hidden}
.detail-scene .art-tree{margin:0 -8px}
.detail-metrics{display:grid;grid-template-columns:repeat(3,1fr);gap:10px;margin:16px 0}
.detail-metrics>div{text-align:center;padding:12px;border-radius:16px;background:rgba(255,253,245,.85);border:1px solid #fff}
.detail-metrics strong{display:block;font:700 22px 'Noto Serif SC';color:#2f6146}
.detail-metrics span{font-size:9px;color:#748177}
.detail-list{display:grid;gap:8px}
.detail-tree{display:flex;align-items:center;gap:10px;padding:12px 14px;border-radius:14px;background:rgba(255,253,245,.85);border:1px solid #fff}
.detail-tree>div{flex:1;display:grid;min-width:0}
.detail-tree b{font-size:12px;color:#33513f}
.detail-tree em{font-style:normal;font-size:9px;color:#8a9990}
.detail-tree strong{font-size:13px;color:#3f6845}
.sheet-like{width:100%;margin-top:16px;padding:14px;border:0;border-radius:16px;background:#fbedcf;color:#a5772e;font-size:13px;display:flex;align-items:center;justify-content:center;gap:7px}
.sheet-like svg{width:16px}
.sheet-like.liked{background:#f6c95b;color:#5a3e10}

/* ============ 设置:精修天气卡 + 土地实时切换 ============ */
.preferences h2{font-size:16px;color:#2b4c3c;margin-top:30px}
.weather-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:10px}
.weather-card{all:unset;cursor:pointer;position:relative;border-radius:20px;overflow:hidden;background:#fffdf5;box-shadow:0 8px 22px rgba(48,74,55,.1);border:2px solid transparent;transition:transform .2s,border-color .2s,box-shadow .2s}
.weather-card:hover{transform:translateY(-3px)}
.weather-card.selected{border-color:#4f9169;box-shadow:0 12px 28px rgba(56,96,67,.24)}
.wc-sky{height:74px;position:relative;display:grid;place-items:center;color:#fff;overflow:hidden}
.wc-sky svg{width:26px;position:relative;z-index:2;filter:drop-shadow(0 2px 4px rgba(0,0,0,.25))}
.wc-fx{position:absolute;inset:0}
.wc-sunny .wc-sky{background:linear-gradient(160deg,#ffe08a,#ffb85e)}
.wc-sunny .wc-fx{background:radial-gradient(circle at 50% 40%,rgba(255,255,255,.75),transparent 55%);animation:glow 4s ease-in-out infinite}
.wc-rain .wc-sky{background:linear-gradient(160deg,#8fb7c4,#5c7f8e)}
.wc-rain .wc-fx{background:repeating-linear-gradient(100deg,transparent 0 9px,rgba(255,255,255,.5) 10px 11px,transparent 12px 21px);animation:rainfx .7s linear infinite}
.wc-sunset .wc-sky{background:linear-gradient(160deg,#ffb17a,#e57ba0 70%,#a56aa8)}
.wc-sunset .wc-fx{background:radial-gradient(circle at 30% 80%,rgba(255,220,150,.6),transparent 50%)}
.weather-card b{display:block;font-size:12px;color:#2f5140;margin:10px 12px 2px}
.weather-card span{display:block;font-size:9px;color:#7d8b81;margin:0 12px 12px;line-height:1.5}
.wc-check{position:absolute;top:8px;right:8px;width:22px;height:22px;border-radius:50%;background:#4f9169;color:#fff;display:grid;place-items:center}
.wc-check svg{width:13px}
@keyframes glow{0%,100%{opacity:.7}50%{opacity:1}}
@keyframes rainfx{to{background-position:0 21px}}

.land-grid{display:grid;grid-template-columns:1fr;gap:10px}
.land-card{all:unset;cursor:pointer;display:flex;align-items:center;gap:14px;padding:12px 14px;border-radius:18px;background:#fffdf5;box-shadow:0 8px 20px rgba(48,74,55,.1);border:2px solid transparent;transition:transform .2s,border-color .2s}
.land-card:hover{transform:translateY(-2px)}
.land-card.selected{border-color:#4f9169;box-shadow:0 12px 26px rgba(56,96,67,.22)}
.land-swatch{width:60px;height:46px;border-radius:12px;flex:0 0 60px;box-shadow:inset 0 -8px 12px rgba(0,0,0,.12)}
.land-card.meadow .land-swatch{background:linear-gradient(180deg,#dcecc7 0 38%,#8fbf6c 39%,#5e9a4c)}
.land-card.forest .land-swatch{background:linear-gradient(180deg,#b7c9b2 0 34%,#4f7d5a 35%,#2f5b40)}
.land-card.autumn .land-swatch{background:linear-gradient(180deg,#f0cf9a 0 36%,#cf8f4e 37%,#9a5e2f)}
.land-copy{flex:1}
.land-copy b{display:block;font-size:13px;color:#2f5140}
.land-copy span{font-size:10px;color:#7d8b81}
.land-check{width:24px;height:24px;border-radius:50%;background:#4f9169;color:#fff;display:grid;place-items:center}
.land-check svg{width:14px}

/* 预览:随天气/土地实时变化 */
.preview{height:190px;border-radius:24px;overflow:hidden;position:relative;display:flex;align-items:flex-end;justify-content:center;padding-bottom:24px;box-shadow:0 12px 28px rgba(54,83,60,.2);border:1px solid #fff;transition:background .4s}
.preview-grove{display:flex;align-items:flex-end;gap:0;z-index:2}
.preview-grove .art-tree{margin:0 -6px}
.preview.land-meadow:not(.home-page):not(.project-page):not(.community){background:linear-gradient(180deg,#e7dcb6 0 44%,#8fbf6c 45%,#5e9a4c)}
.preview.land-forest:not(.home-page):not(.project-page):not(.community){background:linear-gradient(180deg,#c4d2c0 0 42%,#4f7d5a 43%,#2f5b40)}
.preview.land-autumn:not(.home-page):not(.project-page):not(.community){background:linear-gradient(180deg,#f0cf9a 0 42%,#cf8f4e 43%,#9a5e2f)}
.preview.theme-rain{filter:brightness(.94) saturate(.9)}
.preview.theme-sunset{filter:hue-rotate(-8deg) saturate(1.08) brightness(1.02)}
.preview>span{position:absolute;top:12px;left:14px;font-size:9px;color:#fff;background:rgba(40,64,44,.42);padding:5px 10px;border-radius:12px;backdrop-filter:blur(4px);z-index:3}

/* 土地外观:让 land-* 在首页/详情真正生效(更强的色相区分) */
.land-meadow .grove{background:linear-gradient(180deg,rgba(233,220,181,.7) 0 36%,rgba(143,191,108,.85) 37% 69%,rgba(94,154,76,.9) 70%)}
.land-forest .grove{background:linear-gradient(180deg,rgba(196,210,192,.7) 0 34%,rgba(79,125,90,.88) 35% 68%,rgba(47,91,64,.92) 69%)}
.land-autumn .grove{background:linear-gradient(180deg,rgba(240,207,154,.72) 0 36%,rgba(207,143,78,.86) 37% 68%,rgba(154,94,47,.92) 69%)}
.land-forest .home-page,.land-forest.home-page{filter:none}
.land-forest .project,.land-autumn .project{filter:none}
.home-page.land-forest{background-blend-mode:multiply}
.home-page.land-autumn{filter:sepia(.18) saturate(1.12)}
.home-page.land-forest{filter:hue-rotate(8deg) saturate(.92)}

/* ============================================================
   v7 — 管理目标面板 / 土地重设计 / 拜访布局修复 / 土地外观缩略图
   ============================================================ */

/* ---- 首页:管理目标按钮(替代 +新目标) ---- */
.manage-btn{display:inline-flex;align-items:center;gap:5px;background:#fff7dfcc!important;border:0;border-radius:18px;padding:8px 14px;color:#3f6549!important;font-size:11px;box-shadow:0 4px 14px #38543b20}
.manage-btn svg{width:14px}
.plot-del{display:none!important}

/* ---- 管理目标底部抽屉 ---- */
.manage-sheet{position:relative;width:min(100%,480px);margin:auto;max-height:88vh;overflow:auto;padding:26px 22px 30px;border-radius:28px 28px 0 0;background:linear-gradient(180deg,#fbf8f0,#eef2e6);box-shadow:0 -14px 44px rgba(30,50,36,.28)}
.manage-sheet small{color:#8a7a58;letter-spacing:2px}
.manage-sheet h2{font-size:25px;color:#2b4c3c;margin:4px 0}
.manage-lead{font-size:12px;color:#6a7a6f;margin-bottom:18px}
.manage-sheet h3{font-size:14px;color:#33513f;margin:0 0 12px;display:flex;align-items:center;gap:8px}
.manage-add{padding:18px;border-radius:20px;background:rgba(255,255,255,.7);border:1px solid #fff;box-shadow:0 8px 22px rgba(48,74,55,.09)}
.manage-add input{width:100%;padding:14px;border:1px solid #e0dccd;border-radius:14px;background:#fffdf7;font-size:13px}
.tree-pick{display:grid;grid-template-columns:repeat(3,1fr);gap:8px;margin:12px 0}
.tree-pick .tp{all:unset;cursor:pointer;display:flex;flex-direction:column;align-items:center;gap:8px;padding:14px 4px;border-radius:14px;background:#fffdf7;border:2px solid transparent;box-shadow:0 4px 12px rgba(48,74,55,.08)}
.tree-pick .tp.on{border-color:#4f9169;background:#f2f8ee}
.tree-pick .tp i{width:22px;height:30px;display:block}
.tree-pick .tp.pine i{background:linear-gradient(180deg,#3c7a56,#245b40);clip-path:polygon(50% 0,78% 42%,64% 40%,92% 74%,68% 72%,100% 100%,0 100%,32% 72%,8% 74%,36% 40%,22% 42%)}
.tree-pick .tp.poplar i{background:radial-gradient(circle at 50% 42%,#82ad63,#3f7b4c 72%);border-radius:50% 50% 44% 44%/60% 60% 40% 40%}
.tree-pick .tp.fruit i{background:radial-gradient(circle at 32% 30%,#d67f57 0 16%,transparent 17%),radial-gradient(circle at 68% 55%,#c96b4d 0 14%,transparent 15%),radial-gradient(circle at 50% 44%,#7fa860,#3f7b4c 72%);border-radius:50%}
.tree-pick .tp b{font-size:11px;color:#3f6549}
.manage-add .submit{width:100%;display:flex;align-items:center;justify-content:center;gap:7px;padding:14px;border:0;border-radius:14px;background:#2f6146;color:#fff;font-size:13px}
.manage-add .submit:disabled{opacity:.45}
.manage-add .submit svg{width:16px}
.manage-list{margin-top:22px}
.manage-list h3 em{font-style:normal;background:#e7f0e2;color:#3f7150;border-radius:10px;padding:1px 9px;font-size:11px}
.manage-row{display:flex;align-items:center;gap:12px;padding:13px 14px;border-radius:14px;background:rgba(255,255,255,.72);border:1px solid #fff;margin-bottom:8px;box-shadow:0 5px 14px rgba(48,74,55,.07)}
.manage-row .type-dot{width:12px;height:12px;flex:0 0 12px}
.mr-info{flex:1;display:grid;min-width:0}
.mr-info b{font-size:13px;color:#33513f;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.mr-info em{font-style:normal;font-size:10px;color:#8a9990}
.mr-del{flex:0 0 auto;width:34px;height:34px;border:0;border-radius:11px;background:#f7e8e3;color:#b5503f;display:grid;place-items:center}
.mr-del:hover{background:#f0d5cd}
.mr-del svg{width:16px}
.mr-empty{padding:22px;text-align:center;font-size:12px;color:#8a9990}

/* ============ 图二:土地(grove)彻底重设计 ============ */
.grove{height:300px!important;margin:14px 16px 26px!important;padding:0!important;border-radius:26px!important;position:relative;overflow:hidden;box-shadow:0 16px 34px rgba(41,79,62,.24),inset 0 0 0 1px rgba(255,255,255,.5)!important;background:none!important;backdrop-filter:none!important;isolation:isolate}
.grove:before,.grove:after{display:none!important}
.grove-island{position:absolute;inset:0;background-size:cover;background-position:center 46%;z-index:0}
.grove-sky:before{content:'';position:absolute;top:14%;right:16%;width:46px;height:46px;border-radius:50%;background:radial-gradient(circle,#fff6d8,#ffe6a3 70%,transparent);box-shadow:0 0 30px #ffe9ad}
.grove-sky:after{content:'';position:absolute;top:26%;left:10%;width:120px;height:26px;border-radius:20px;background:rgba(255,255,255,.7);filter:blur(6px)}
.grove-ground{position:absolute;left:0;right:0;bottom:0;height:52%;z-index:1;background:linear-gradient(180deg,#8fc06b 0%,#6ba85a 26%,#8a7247 46%,#6f5a38 100%);border-radius:44% 56% 0 0/40px 46px 0 0;box-shadow:inset 0 8px 18px rgba(255,255,255,.28),inset 0 -30px 40px rgba(56,44,26,.35)}
.grove-ground:before{content:'';position:absolute;left:0;right:0;top:24%;height:6px;background:repeating-linear-gradient(90deg,transparent 0 14px,rgba(70,55,32,.18) 15px 17px);opacity:.7}
.grove-ground:after{content:'专注的每一分钟，都留在这片土地上';position:absolute;left:0;right:0;bottom:10px;text-align:center;color:#f3ead2;font-size:9px;letter-spacing:1px;text-shadow:0 1px 2px rgba(60,45,25,.5)}
.grove-trees{position:absolute;left:0;right:0;bottom:0;height:100%;z-index:2;display:flex;align-items:flex-end;justify-content:center;gap:0;padding:0 40px 78px}
.grove-trees .art-tree{margin:0 -6px}
.grove-empty{color:#4a6553;font-size:11px;align-self:center;text-align:center;padding:0 30px;background:rgba(255,255,255,.65);border-radius:12px;padding:10px 16px}
.land-forest .grove-sky{background:linear-gradient(180deg,#a9cfd0 0%,#cfe4dc 44%,#e2ece0 62%)}
.land-forest .grove-ground{background:linear-gradient(180deg,#6fa06a 0%,#4f7d5a 28%,#5a4d34 50%,#40331f 100%)}
.land-autumn .grove-sky{background:linear-gradient(180deg,#f3d9b4 0%,#f6e6cf 46%,#f2ecdd 64%)}
.land-autumn .grove-ground{background:linear-gradient(180deg,#e0b972 0%,#cf8f4e 26%,#9a6a38 48%,#6f4a26 100%)}

/* ============ 图三:拜访布局修复 ============ */
.nb-card{border-radius:24px;overflow:hidden;background:rgba(255,253,244,.94);box-shadow:0 15px 34px rgba(52,90,61,.2);backdrop-filter:blur(12px);border:1px solid #fff;margin:16px 4px;padding:16px}
.nb-card .neighbor-scene{all:unset;box-sizing:border-box;padding:0;margin:0;cursor:pointer;display:block;position:relative;width:100%;height:170px;overflow:hidden;border-radius:16px}
.nb-island{position:absolute;inset:0;background-size:cover;background-position:center 46%;z-index:0}
.nb-sky:before{content:'';position:absolute;top:16%;right:14%;width:38px;height:38px;border-radius:50%;background:radial-gradient(circle,#fff6d8,#ffe6a3 70%,transparent);box-shadow:0 0 24px #ffe9ad}
.neighbor-scene .nb-trees{position:absolute;left:0;right:0;bottom:0;height:100%;z-index:2;display:flex;align-items:flex-end;justify-content:center;padding:0 30px 56px;gap:0}
.neighbor-scene .nb-trees .art-tree{margin:0 -8px;height:132px;width:66px;flex-basis:52px}
.neighbor-scene:after{content:'';position:absolute;left:0;right:0;bottom:0;height:46%;z-index:1;background:linear-gradient(180deg,#8fc06b 0%,#6ba85a 30%,#7d6743 60%,#5f4d30 100%);border-radius:40% 60% 0 0/30px 34px 0 0;box-shadow:inset 0 -20px 30px rgba(56,44,26,.3)}
.land-forest.neighbor-scene:after,.neighbor-scene.land-forest:after{background:linear-gradient(180deg,#6fa06a 0%,#4f7d5a 30%,#4c3f28 62%,#3a2f1c 100%)}
.land-autumn.neighbor-scene:after,.neighbor-scene.land-autumn:after{background:linear-gradient(180deg,#e0b972 0%,#cf8f4e 30%,#8a6030 62%,#654325 100%)}
.land-forest.neighbor-scene .nb-sky{background:linear-gradient(180deg,#aacfd0 0%,#cfe4dc 46%,#e2ece0 64%)}
.land-autumn.neighbor-scene .nb-sky{background:linear-gradient(180deg,#f3d9b4 0%,#f6e6cf 46%,#f2ecdd 64%)}
.neighbor-scene .art-tree span{display:none} /* 场景横幅里不显示 xxm 分钟标签,移到明细 */
.neighbor-scene .peek{position:absolute;right:12px;bottom:10px;z-index:3;font-size:10px;color:#fff;background:rgba(40,64,44,.55);padding:6px 11px;border-radius:13px;backdrop-filter:blur(4px)}
.nb-card section{padding:15px 16px 16px;display:grid;gap:5px}
.nb-card section b{font-size:16px;color:#2b4c3c}
.nb-card section>span{font-size:10px;color:#748177}

/* 拜访详情弹层的场景同样加天空 */
.detail-scene{position:relative;padding:0!important;overflow:hidden;background:none!important;box-shadow:0 0 0 1px rgba(255,255,255,.4) inset!important}
.detail-scene .nb-sky:before{width:44px;height:44px}
.detail-scene .nb-trees{position:absolute;left:0;right:0;bottom:0;height:100%;z-index:2;display:flex;align-items:flex-end;justify-content:center;padding:0 18px 26px}
.detail-scene:after{content:'';position:absolute;left:0;right:0;bottom:0;height:46%;z-index:1;background:linear-gradient(180deg,#8fc06b 0%,#6ba85a 30%,#7d6743 60%,#5f4d30 100%);border-radius:40% 60% 0 0/30px 34px 0 0}
.detail-scene .art-tree span{display:none}
.garden-detail.land-forest .detail-scene:after{background:linear-gradient(180deg,#6fa06a 0%,#4f7d5a 30%,#4c3f28 62%,#3a2f1c 100%)}
.garden-detail.land-autumn .detail-scene:after{background:linear-gradient(180deg,#e0b972 0%,#cf8f4e 30%,#8a6030 62%,#654325 100%)}
.garden-detail.land-forest .detail-scene .nb-sky{background:linear-gradient(180deg,#aacfd0 0%,#cfe4dc 46%,#e2ece0 64%)}
.garden-detail.land-autumn .detail-scene .nb-sky{background:linear-gradient(180deg,#f3d9b4 0%,#f6e6cf 46%,#f2ecdd 64%)}

/* ============ 图四:土地外观改为迷你风景缩略图 ============ */
.land-card{padding:0!important;overflow:hidden;align-items:stretch!important;gap:0!important}
.land-swatch{width:96px!important;height:auto!important;flex:0 0 96px!important;border-radius:0!important;position:relative;overflow:hidden;box-shadow:none!important;background:none!important}
.land-swatch:before{content:'';position:absolute;inset:0;z-index:0}
.land-swatch:after{content:'';position:absolute;left:0;right:0;bottom:0;height:52%;z-index:1;border-radius:38% 62% 0 0/22px 26px 0 0}
.land-card.meadow .land-swatch:before{background:linear-gradient(180deg,#c8e6ef,#e4f2e0)}
.land-card.meadow .land-swatch:after{background:linear-gradient(180deg,#8fc06b,#5e9a4c 70%,#4a7a3c)}
.land-card.forest .land-swatch:before{background:linear-gradient(180deg,#b6d3d1,#dbe8de)}
.land-card.forest .land-swatch:after{background:linear-gradient(180deg,#5c8f66,#3a6247 70%,#2f5b40)}
.land-card.autumn .land-swatch:before{background:linear-gradient(180deg,#f3dcbb,#f4ecdc)}
.land-card.autumn .land-swatch:after{background:linear-gradient(180deg,#e0b972,#c07f42 70%,#9a5e2f)}
/* 缩略图里的小树剪影 */
.land-swatch em{position:absolute;z-index:2;bottom:22%;width:12px;height:20px;background:#2f5b40;clip-path:polygon(50% 0,80% 55%,64% 52%,100% 100%,0 100%,36% 52%,20% 55%)}
.land-swatch .t1{left:26%;bottom:24%}
.land-swatch .t2{left:50%;height:24px;bottom:22%}
.land-swatch .t3{left:70%;height:16px;bottom:26%}
.land-card.autumn .land-swatch em{background:#7a4a24}
.land-card.forest .land-swatch em{background:#243f2c}
.land-copy{flex:1;padding:16px 16px}
.land-card.selected .land-swatch:before{filter:brightness(1.02)}
/* 修正选中态深底导致文字看不清:选中只描边不填深色 */
.land-card.selected{background:#f2f8ee!important;border-color:#4f9169!important}
.land-copy b{color:#2f5140!important}
.land-copy span{color:#7d8b81!important}
.land-check{margin:auto 14px}

/* land-grid 保持单列即可,land-card 已是横向 */
.land-grid{gap:12px}

/* ---- v8 首页微调:移除迷惑的「芽」浮标 + 目标土地标题排版 ---- */
.guide{display:none!important}
.title-row{padding:0 22px!important;margin:4px 0 10px;align-items:center}
.title-row h2{font-size:20px!important;line-height:1.4;color:#284c3b;margin:0!important;padding:2px 0;overflow:visible;white-space:nowrap}

/* ============================================================
   v9 — 卡片标签右移 / 新增树种 / 花草(短时任务)
   ============================================================ */

/* ---- 修复:01/松树林 等编号林名标签太偏左被遮 ---- */
.project-copy{padding-left:6px}
.project-copy small{display:inline-block;padding:3px 10px;margin-bottom:6px;border-radius:999px;background:rgba(63,101,73,.1);color:#3f6549!important;font-size:11px;letter-spacing:.5px;white-space:nowrap}
.poster-1 .project-copy small{background:rgba(150,90,45,.12);color:#8a5a2c!important}
.poster-2 .project-copy small{background:rgba(70,90,120,.12);color:#4a5b78!important}

/* ---- 新增树种:管理面板选择器缩略图 ---- */
.tree-pick{grid-template-columns:repeat(3,1fr)}
.tree-pick .tp.sakura i{background:radial-gradient(circle at 38% 32%,#f3d6e0 0 40%,transparent 41%),radial-gradient(circle at 66% 56%,#e9c3d2 0 34%,transparent 35%),radial-gradient(circle at 50% 46%,#e7cdd6,#9fb27a 96%);border-radius:50% 50% 46% 46%/60% 60% 42% 42%}
.tree-pick .tp.maple i{background:radial-gradient(circle at 40% 34%,#f0a24d 0 34%,transparent 35%),radial-gradient(circle at 66% 52%,#e0632f 0 30%,transparent 31%),radial-gradient(circle at 50% 46%,#e2793a,#c0451f 74%);border-radius:50% 50% 46% 46%/58% 58% 44% 44%}
.tree-pick .tp.bamboo i{background:linear-gradient(92deg,#5aa155 0 22%,transparent 22% 30%,#6cb85f 30% 52%,transparent 52% 60%,#7cc267 60% 82%);border-radius:6px}

/* ---- 新增树种:统计页种类圆点 ---- */
.type-dot.sakura{background:#e0aec2}
.type-dot.maple{background:#d9622e}
.type-dot.bamboo{background:#5aa155}

/* ---- 花草(短时任务)呈现 ---- */
.art-tree.flower img{filter:drop-shadow(0 6px 8px rgba(60,80,50,.18))}
.grove-trees .art-tree.flower,.mini-grove .art-tree.flower{align-self:flex-end}
.art-tree.flower img{object-position:bottom}
.art-tree.flower::after{width:64%}
.flower-tag{font-style:normal;margin-left:8px;font-size:10px;color:#c76aa0;background:#fbe8f1;border-radius:8px;padding:1px 8px;vertical-align:middle}

/* v10 卡片标题再右移,更舒适 */
.plots .project .project-copy{padding-left:22px!important}

/* ===== v13 · 用真实雨林土壤照片当地面,去掉杂草 ===== */
.grove-ground{background-size:cover!important;background-position:center bottom!important;background-repeat:no-repeat!important;background-blend-mode:normal!important;border-radius:44% 56% 9px 9px/34px 40px 9px 9px!important;box-shadow:inset 0 8px 16px rgba(120,96,60,.22),inset 0 -26px 34px rgba(20,14,6,.5)!important}
.nb-ground,.detail-scene .nb-ground{position:absolute;left:0;right:0;bottom:0;height:48%;z-index:1;background-size:cover;background-position:center bottom;background-repeat:no-repeat;border-radius:40% 60% 0 0/26px 30px 0 0;box-shadow:inset 0 -18px 26px rgba(20,14,6,.42)}
/* 盖住旧的纯色 :after 地面 */
.neighbor-scene:after,.detail-scene:after{display:none!important}
/* 树木底部下沉,扎进土里 */
.grove-trees{padding-bottom:26px!important}
.nb-trees{padding-bottom:20px!important}
.detail-scene .nb-trees{padding-bottom:22px!important}
/* 树根贴地阴影(土壤上更深一点) */
.art-tree::after{background:radial-gradient(ellipse,rgba(15,10,4,.5),transparent 70%)!important;height:12px!important;width:58%!important;bottom:4px!important}

/* ===== v14 · 移植"心愿花园"功能:星光/连签/成林进度/激励/社交 ===== */

/* —— 首页顶部花园星光徽章 —— */
.star-pill{display:inline-flex;align-items:center;gap:8px;padding:7px 16px 7px 8px;border-radius:22px;background:linear-gradient(135deg,rgba(255,253,244,.94),rgba(236,243,230,.94));color:#3f6549;font:700 16px 'Noto Serif SC';letter-spacing:.5px;border:1px solid rgba(160,190,155,.55);box-shadow:0 6px 16px rgba(90,130,95,.16),inset 0 1px 0 rgba(255,255,255,.85);white-space:nowrap}
.star-pill .star-svg{width:22px;height:22px;padding:3px;border-radius:50%;background:radial-gradient(circle at 50% 40%,#ffffff,#eef4e6);box-shadow:0 1px 3px rgba(90,130,95,.22),inset 0 1px 1px rgba(255,255,255,.9);filter:drop-shadow(0 1px 1px rgba(120,150,110,.25))}
.star-svg{display:block}

/* —— 首页目标卡·成林进度条 —— */
.plot-prog{margin-top:10px;height:7px;border-radius:6px;background:rgba(120,140,120,.22);overflow:hidden}
.project .project-open>.plot-foot{position:absolute;left:21px;right:21px;bottom:16px;z-index:6}
.plot-foot .plot-prog{margin-top:0}.plot-foot .plot-meta{display:flex;align-items:baseline;justify-content:space-between;margin-bottom:7px}.plot-foot .plot-meta span{font-size:10px;color:#6a7a6c;font-weight:600}
.plot-foot .plot-prog-txt{margin-top:0}
.plot-prog i{display:block;height:100%;border-radius:6px;background:linear-gradient(90deg,#7fc08a,#2f8f5b);transition:width .6s cubic-bezier(.2,.8,.2,1)}
.plot-prog-txt{display:block;margin-top:5px;font-size:10px;color:#5c7a63;font-weight:600}

/* —— 统计页·荣誉指标区 —— */
.metrics.honor{margin-top:12px}
.metrics.honor .metric{background:linear-gradient(160deg,#fffaf0,#fdf1d8);border:1px solid #f4e3bd}
.metrics.honor .metric-ico{background:linear-gradient(135deg,#ffe6a3,#f4c65a);color:#8a5c10}
.metrics.honor .metric strong{color:#8a5c10}

/* —— 统计页·成林进度 —— */
.forest-progress{display:grid;gap:12px;margin-bottom:6px}
.fp-row{display:flex;align-items:center;gap:10px}
.fp-row b{font-size:12px;color:#3a4b3f;min-width:88px;max-width:88px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.fp-bar{flex:1;height:9px;border-radius:7px;background:rgba(120,140,120,.2);overflow:hidden}
.fp-bar i{display:block;height:100%;border-radius:7px;background:linear-gradient(90deg,#8fd39c,#2f8f5b);transition:width .6s cubic-bezier(.2,.8,.2,1)}
.fp-row em{font-style:normal;font-size:11px;color:#5c7a63;font-weight:700;min-width:38px;text-align:right}

/* —— 统计页·坚持的力量激励卡（温暖版）—— */
.power-card.warm{position:relative;display:flex;align-items:center;gap:16px;padding:20px 22px;border-radius:24px;background:linear-gradient(150deg,#fff6ec 0%,#fdeede 45%,#f6f2df 100%);border:1px solid #f1e2c9;box-shadow:0 10px 26px rgba(190,150,90,.16);overflow:hidden}
.power-card.warm .power-glow{position:absolute;top:-42px;right:-30px;width:150px;height:150px;border-radius:50%;background:radial-gradient(circle,rgba(255,214,150,.55),rgba(255,214,150,0) 70%);pointer-events:none}
.power-card.warm .power-emoji{position:relative;font-size:40px;line-height:1;flex-shrink:0;filter:drop-shadow(0 4px 6px rgba(160,120,60,.22))}
.power-card.warm .power-body{position:relative;flex:1;display:flex;flex-direction:column;gap:12px;min-width:0}
.power-card.warm .power-body p{font:600 14px/1.7 'Noto Serif SC';color:#6a4f2c;margin:0}
.power-card.warm .power-chips{display:flex;flex-wrap:wrap;gap:8px}
.power-card.warm .power-chips span{display:inline-flex;align-items:baseline;gap:4px;font-size:11px;color:#8a6a3c;background:rgba(255,255,255,.66);border:1px solid rgba(240,220,180,.9);border-radius:12px;padding:5px 11px;backdrop-filter:blur(3px)}
.power-card.warm .power-chips b{font-size:15px;font-weight:800;color:#c8892f}
/* —— 统计页·激励卡(与森林绿协调的沉静版) —— */
.power-card.calm{position:relative;display:flex;align-items:center;gap:16px;margin:22px 0;padding:20px 22px;border-radius:24px;background:linear-gradient(150deg,#f4f9f0 0%,#eef5ea 55%,#f7f4e9 100%);border:1px solid #dfe9d6;box-shadow:0 10px 24px rgba(90,130,95,.14);overflow:hidden}
.power-card.calm .power-emoji{position:relative;font-size:38px;line-height:1;flex-shrink:0;filter:drop-shadow(0 4px 6px rgba(80,120,80,.2))}
.power-card.calm .power-body{position:relative;flex:1;display:flex;flex-direction:column;gap:12px;min-width:0}
.power-card.calm .power-body p{font:600 14px/1.7 'Noto Serif SC';color:#3f5a45;margin:0}
.power-card.calm .power-chips{display:flex;flex-wrap:wrap;gap:8px}
.power-card.calm .power-chips span{display:inline-flex;align-items:baseline;gap:4px;font-size:11px;color:#5c7a63;background:rgba(255,255,255,.7);border:1px solid #d8e6d2;border-radius:12px;padding:5px 11px}
.power-card.calm .power-chips b{font-size:15px;font-weight:800;color:#2f8f5b}

/* —— 统计页·各土地投入进度 —— */
.stat .stat-info{flex:1;display:flex;flex-direction:column;gap:5px;min-width:0}
.stat .stat-info b{font-size:13px;color:#3a4b3f;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.stat .stat-info span{font-size:10px;color:#8a9488}
.stat .stat-prog{width:100%;height:7px;border-radius:6px;background:rgba(120,140,120,.18);overflow:hidden}
.stat .stat-prog i{display:block;height:100%;border-radius:6px;background:linear-gradient(90deg,#8fd39c,#2f8f5b);transition:width .6s cubic-bezier(.2,.8,.2,1)}.stats-page .stat{height:84px;align-items:center}.stats-page .stat .art-tree{height:66px;width:60px;align-self:center}.stats-page .stat .stat-info{transform:translateY(11px)}.stats-page .stat>strong{display:flex;align-items:baseline;gap:2px;margin-right:24px;transform:translateY(11px);font:700 22px 'Noto Serif SC';color:#2f6146;line-height:1}.stats-page .stat>strong em{font:600 11px 'Noto Sans SC';font-style:normal;color:#8a9990}
.stat>strong{font-size:12px;color:#5c7a63;font-weight:700;margin-left:10px;white-space:nowrap}

/* —— 拜访页·邻居头像与郁郁葱葱度 —— */
.nb-head{display:flex;align-items:center;gap:12px;margin-bottom:12px}
.nb-avatar{width:44px;height:44px;border-radius:50%;display:grid;place-items:center;font-size:22px;background:linear-gradient(135deg,#fdf1d8,#f6e2b8);box-shadow:inset 0 1px 0 rgba(255,255,255,.7),0 4px 10px rgba(180,150,80,.24)}
.nb-head b{font:700 15px 'Noto Serif SC';color:#2b4c3c}
.nb-bloom{display:block;font-style:normal;font-size:11px;color:#8a7a58;margin-top:2px}

/* —— 拜访页·场景内成树计数 —— */
.nb-treecount{position:absolute;right:12px;bottom:10px;font-size:10px;color:#fff;background:rgba(40,64,44,.55);padding:5px 10px;border-radius:12px;backdrop-filter:blur(4px);z-index:3}

/* —— 拜访页·社交动作按钮(覆盖旧的 nb-view/nb-like) —— */
.nb-actions{display:flex;gap:8px;margin-top:12px}
.nb-act{flex:1;display:inline-flex;align-items:center;justify-content:center;gap:6px;border:1px solid #d8e1d6;background:#fff;color:#3f6845;border-radius:14px;padding:10px 8px;font-size:11px;font-weight:600;cursor:pointer;transition:.2s}
.nb-act svg{width:14px;height:14px}
.nb-act:active{transform:scale(.96)}
.nb-act.primary{background:#eef6ee;border-color:#cfe0cf}
.nb-act.warm{background:#fbedcf;border-color:#f0dcae;color:#a5772e}
.nb-act.on{background:#f6c95b;border-color:#eab63c;color:#5a3e10}
.nb-act.warm.on{background:#8fc79a;border-color:#6faa7c;color:#1f4d30}

/* —— 拜访页·留言列表与输入 —— */
.nb-comments{margin-top:12px;display:grid;gap:7px}
.nb-cmt{font-size:11.5px;line-height:1.6;color:#4a5b50;background:rgba(120,150,120,.08);border-radius:10px;padding:7px 11px}
.nb-cmt b{color:#2f6146;font-weight:700}
.nb-cmt-form{display:flex;align-items:center;gap:8px;margin-top:6px;width:auto;padding:0;background:none}
.detail-comments .nb-cmt-form{width:auto;padding:0;background:none}
.nb-cmt-form input{flex:1;border:1px solid #dbe3d9;border-radius:12px;padding:9px 12px;font-size:12px;background:#fff;outline:none}
.nb-cmt-form input:focus{border-color:#8fc79a}
.nb-cmt-form button{width:38px;height:38px;flex:none;align-self:center;border:0;border-radius:12px;background:#2f8f5b;color:#fff;display:grid;place-items:center;cursor:pointer}
.nb-cmt-form button svg{width:16px;height:16px}

/* —— 详情弹层·社交动作与留言 —— */
.detail-actions{display:flex;gap:10px;margin:16px 0 6px}
.detail-actions .nb-act{flex:1}
.detail-comments{margin-top:14px;display:grid;gap:8px}
.detail-comments h3{font:700 13px 'Noto Serif SC';color:#2b4c3c;margin:0 0 2px}

/* —— 设置页·我的荣誉 —— */
.honor-lead{font-size:11px;line-height:1.7;color:#7a8a7c;margin:-4px 0 14px}
.honor-grid{display:grid;grid-template-columns:repeat(2,1fr);gap:10px;margin-bottom:8px}
.honor-card{position:relative;display:flex;flex-direction:column;align-items:center;gap:5px;padding:14px 12px;border-radius:18px;background:linear-gradient(160deg,#fbfcf7,#eef4e9);border:1px solid #dfe9d6;box-shadow:0 5px 14px rgba(90,130,95,.09)}
.honor-ico{width:38px;height:38px;border-radius:50%;display:grid;place-items:center;font-size:18px;background:linear-gradient(135deg,#eef4ea,#d6e8cf);color:#2f8f5b}
.honor-ico-star{background:linear-gradient(135deg,#f3f7ec,#dcecd0);box-shadow:0 4px 10px rgba(120,150,110,.22)}
.honor-ico svg{width:20px;height:20px}
.honor-ico-star .star-svg{width:24px;height:24px}
.honor-card strong{font:800 22px 'Noto Serif SC';color:#2f6146;line-height:1}
.honor-card em{font-style:normal;font-size:11px;color:#6a7a6c;font-weight:600}

/* ===== v15 · 喜羊羊卡通扁平画风:天空/草地/树木阴影全部改造 ===== */

/* —— 卡通蓝天(带简单太阳 + 云朵) —— */
.grove-sky,.nb-sky,.detail-scene .nb-sky{background:linear-gradient(180deg,#8fd6f5 0%,#bfe9fb 55%,#e6f7e0 100%)!important}
.grove-sky:before,.nb-sky:before{content:'';position:absolute;top:12%;right:14%;width:52px;height:52px;border-radius:50%;background:#ffe14d!important;box-shadow:0 0 0 6px rgba(255,240,140,.5),0 0 0 3px #f5c518 inset!important;filter:none!important}
.grove-sky:after{content:'';position:absolute;top:22%;left:10%;width:88px;height:24px;border-radius:20px;background:#fff!important;box-shadow:22px 6px 0 -3px #fff,-16px 5px 0 -4px #fff!important;filter:none!important}
.nb-sky:before{width:38px;height:38px}

/* —— 卡通扁平草地(亮绿圆丘 + 波浪草边 + 深绿描边) —— */
.grove-ground,.nb-ground,.detail-scene .nb-ground{
 background:linear-gradient(180deg,#7ed957 0%,#5cc23f 40%,#48a832 100%)!important;
 background-size:auto!important;background-blend-mode:normal!important;
 border-radius:46% 54% 8px 8px/22px 26px 8px 8px!important;
 box-shadow:inset 0 4px 0 #a6ec7d,inset 0 -18px 26px rgba(30,110,40,.28)!important;
 border-top:4px solid #2f7d2a!important}
/* 草地上的波浪草丛顶边(卡通锯齿) */
.grove-ground:before{content:''!important;position:absolute!important;left:0;right:0;top:-11px;height:14px;
 background:radial-gradient(circle at 10px 14px,#5cc23f 9px,transparent 10px) repeat-x;
 background-size:22px 14px!important;filter:none!important;opacity:1!important}
.grove-ground:after{display:none!important}
.nb-ground,.detail-scene .nb-ground{height:50%!important;border-top-width:3px!important}

/* —— 隐藏旧的写实纯色地面(neighbor/detail 的 :after 已经隐藏,这里再兜底) —— */
.neighbor-scene:after,.detail-scene:after{display:none!important}

/* —— 树木:去掉写实投影,换成卡通扁平贴地小阴影;保留 PNG 自带黑描边 —— */
.art-tree img,.art-tree.complete img{filter:drop-shadow(0 3px 1px rgba(30,90,40,.28))!important;image-rendering:auto}
.art-tree.flower img{filter:drop-shadow(0 2px 1px rgba(30,90,40,.25))!important}
.art-tree::after{content:''!important;background:rgba(38,110,45,.32)!important;height:9px!important;width:52%!important;bottom:3px!important;border-radius:50%!important;filter:blur(1px)!important}

/* —— 首页目标卡缩略园 & 迷你林同款卡通阴影 —— */
.mini-grove .art-tree img{filter:drop-shadow(0 2px 1px rgba(30,90,40,.25))!important}

/* —— 场景整体去掉写实滤镜(sepia/saturate),回归鲜亮卡通 —— */
.grove{filter:none!important}

/* ===== v16 · 好友申请审批 + 我的(好友/留言/点赞)管理 ===== */

/* —— 广场/我的 分段切换 —— */
.visit-tabs{display:flex;gap:8px;margin:14px 0 18px;padding:5px;background:#eef2e8;border-radius:16px}
.visit-tabs button{flex:1;border:0;background:none;padding:10px 8px;border-radius:12px;font-size:12px;font-weight:600;color:#5c7a63;cursor:pointer;transition:.2s}
.visit-tabs button.on{background:#fff;color:#2f8f5b;box-shadow:0 2px 8px rgba(60,120,84,.16)}

/* —— 加好友"申请中"状态 —— */
.nb-act.warm.pending{background:#f0ece0;border-color:#ddd6c2;color:#9a8f74}
.nb-friend-tag{margin-left:auto;align-self:center;font-size:10px;font-weight:700;color:#2f8f5b;background:#e4f5e6;border:1px solid #b9e3c1;border-radius:10px;padding:3px 9px}

/* —— 我的社交管理页 —— */
.my-social{display:grid;gap:22px}
.ms-block{display:grid;gap:9px}
.ms-block .sec-title{display:flex;align-items:center;gap:8px;margin:0 0 2px}
.ms-block .sec-title em{font-style:normal;font-size:11px;font-weight:700;color:#fff;background:#2f8f5b;border-radius:10px;padding:2px 8px;min-width:20px;text-align:center}
.ms-empty{font-size:12px;color:#8a9990;padding:14px 14px;background:#f4f6f1;border-radius:14px;line-height:1.6}
.ms-row{display:flex;align-items:center;gap:11px;padding:11px 12px;border-radius:16px;background:#fff;border:1px solid #eceee7;box-shadow:0 3px 10px rgba(60,90,64,.05)}
.nb-avatar.sm{width:38px;height:38px;font-size:18px;flex-shrink:0}
.ms-info{flex:1;min-width:0;cursor:default}
.ms-info b{display:block;font:700 13px 'Noto Serif SC';color:#2b4c3c}
.ms-info em{display:block;font-style:normal;font-size:11px;color:#7a8a7f;margin-top:2px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.ms-btn{border:0;border-radius:12px;padding:8px 14px;font-size:11px;font-weight:600;cursor:pointer;flex-shrink:0}
.ms-btn.ghost{background:#eef2e8;color:#5c7a63}
.ms-btn.danger{background:#fbe9e6;color:#c25a45}

/* —— 轻提示 toast —— */
.visit-toast{position:fixed;left:50%;bottom:96px;transform:translateX(-50%);z-index:60;max-width:88%;background:rgba(40,60,44,.94);color:#fff;font-size:12px;line-height:1.5;padding:11px 18px;border-radius:16px;box-shadow:0 10px 28px rgba(20,40,26,.34);animation:toastIn .28s ease}
@keyframes toastIn{from{opacity:0;transform:translate(-50%,10px)}to{opacity:1;transform:translate(-50%,0)}}

/* ===== v17 · 柔光 painterly 画风(吉卜力):替换卡通扁平,回归柔和真实 ===== */

/* —— 关掉 v15 卡通的太阳/云朵/锯齿草边等伪元素 —— */
.grove-sky:before,.grove-sky:after,.nb-sky:before,.nb-sky:after,
.grove-ground:before,.grove-ground:after,.nb-ground:before,.nb-ground:after{content:none!important;display:none!important}

/* —— 天空 = 柔光花园背景图(painterly) —— */
.grove-sky,.nb-sky,.detail-scene .nb-sky{
 background-size:cover!important;
 background-position:center 22%!important;
 background-repeat:no-repeat!important;
 filter:none!important}

/* —— 地面 = 柔和草地纹理,顶边用遮罩羽化,自然融进背景,不再是硬边绿丘 —— */
.grove-ground,.nb-ground,.detail-scene .nb-ground{
 background-size:cover!important;
 background-position:center bottom!important;
 background-repeat:no-repeat!important;
 background-blend-mode:normal!important;
 border:0!important;border-top:0!important;
 border-radius:0!important;
 box-shadow:inset 0 26px 30px -14px rgba(120,140,70,.35)!important;
 -webkit-mask-image:linear-gradient(180deg,transparent 0,#000 26%)!important;
         mask-image:linear-gradient(180deg,transparent 0,#000 26%)!important}
.grove-ground{height:56%!important}
.nb-ground,.detail-scene .nb-ground{height:52%!important}

/* —— 场景整体加一层暖色柔光叠层,让树和地面统一在金绿氛围里 —— */
.grove:after{content:'';position:absolute;inset:0;z-index:3;pointer-events:none;
 background:radial-gradient(120% 80% at 50% 8%,rgba(255,244,200,.32),transparent 52%),
            linear-gradient(180deg,rgba(255,250,225,.14),transparent 30%);
 mix-blend-mode:soft-light}

/* —— 树木:去掉卡通硬阴影,换成柔和自然的落地投影 + 轻微暖色调 —— */
.art-tree img,.art-tree.complete img{
 filter:drop-shadow(0 8px 10px rgba(70,90,50,.28)) saturate(1.04) brightness(1.02)!important}
.art-tree.flower img{
 filter:drop-shadow(0 5px 7px rgba(70,90,50,.24)) saturate(1.03)!important}
.mini-grove .art-tree img{
 filter:drop-shadow(0 5px 7px rgba(70,90,50,.24)) saturate(1.03)!important}
.art-tree::after{
 content:''!important;background:radial-gradient(ellipse,rgba(60,80,40,.28),transparent 72%)!important;
 height:14px!important;width:60%!important;bottom:2px!important;border-radius:50%!important;filter:blur(3px)!important}

/* —— 缩略园/迷你林也吃同一套背景;首页目标卡里的迷你林保持透明,只在土地页展示背景 —— */
.grove{filter:none!important}

/* ===== v18 · 手绘插画风(去柔光,舒适真实)+ 社交动作时间 ===== */
/* 让手绘背景图直接呈现:关掉贴上去的卡通太阳/云/柔光 */
.grove-sky,.nb-sky,.detail-scene .nb-sky{
  background:#cfe6f0 !important;
  background-size:cover !important;background-position:center top !important;background-repeat:no-repeat !important;
}
.grove-sky:before,.grove-sky:after,
.nb-sky:before,.nb-sky:after,
.detail-scene .nb-sky:before,.detail-scene .nb-sky:after{content:none !important;display:none !important;background:none !important;box-shadow:none !important}
/* 关掉暖色柔光叠层,回到干净的手绘质感 */
.grove:after,.grove::after{content:none !important;display:none !important;background:none !important}
.grove-ground,.nb-ground,.detail-scene .nb-ground{
  background-size:cover !important;background-position:center bottom !important;background-repeat:no-repeat !important;
  -webkit-mask-image:linear-gradient(180deg,transparent 0,#000 14%) !important;
  mask-image:linear-gradient(180deg,transparent 0,#000 14%) !important;
}
/* 树木阴影更干净、贴地,不发光 */
.art-tree img,.art-tree.complete img{
  filter:drop-shadow(0 3px 2px rgba(40,70,45,.26)) !important;
}
.art-tree.flower img{filter:drop-shadow(0 2px 1px rgba(40,70,45,.22)) !important}
.art-tree::after{
  content:'' !important;background:rgba(40,80,45,.28) !important;
  height:8px !important;width:50% !important;bottom:4px !important;border-radius:50% !important;filter:blur(1.5px) !important;
}
/* 社交动作时间戳 */
.ms-info em time,.ms-info em{color:#8a7a5f}
.ms-info em time{font-variant-numeric:tabular-nums;opacity:.82}
.nb-cmt .cmt-time{display:inline-block;margin-left:8px;font-size:10px;color:#a99a7e;font-variant-numeric:tabular-nums;opacity:.85}
/* v33 · 新建任务时选择树种 */
.task-tree-pick{margin:2px 20px 0}
.task-tree-pick .ttp-label{display:block;font-size:10px;color:#7d8b81;letter-spacing:1px;margin:0 2px 8px}
.task-tree-pick .ttp-row{display:grid;grid-template-columns:repeat(6,1fr);gap:6px}
.task-tree-pick .ttp{all:unset;cursor:pointer;display:flex;flex-direction:column;align-items:center;gap:5px;padding:9px 2px;border-radius:12px;background:#fffdf7;border:2px solid transparent;box-shadow:0 3px 9px rgba(48,74,55,.08);transition:border-color .15s,background .15s}
.task-tree-pick .ttp.on{border-color:#4f9169;background:#f2f8ee}
.task-tree-pick .ttp i{width:18px;height:24px;display:block}
.task-tree-pick .ttp b{font-size:9px;color:#3f6549;line-height:1}
.task-tree-pick .ttp.pine i{background:linear-gradient(180deg,#3c7a56,#245b40);clip-path:polygon(50% 0,78% 42%,64% 40%,92% 74%,68% 72%,100% 100%,0 100%,32% 72%,8% 74%,36% 40%,22% 42%)}
.task-tree-pick .ttp.poplar i{background:radial-gradient(circle at 50% 42%,#82ad63,#3f7b4c 72%);border-radius:50% 50% 44% 44%/60% 60% 40% 40%}
.task-tree-pick .ttp.fruit i{background:radial-gradient(circle at 32% 30%,#d67f57 0 16%,transparent 17%),radial-gradient(circle at 68% 55%,#c96b4d 0 14%,transparent 15%),radial-gradient(circle at 50% 44%,#7fa860,#3f7b4c 72%);border-radius:50%}
.task-tree-pick .ttp.sakura i{background:radial-gradient(circle at 38% 32%,#f3d6e0 0 40%,transparent 41%),radial-gradient(circle at 66% 56%,#e9c3d2 0 34%,transparent 35%),radial-gradient(circle at 50% 46%,#e7cdd6,#9fb27a 96%);border-radius:50% 50% 46% 46%/60% 60% 42% 42%}
.task-tree-pick .ttp.maple i{background:radial-gradient(circle at 40% 34%,#f0a24d 0 34%,transparent 35%),radial-gradient(circle at 66% 52%,#e0632f 0 30%,transparent 31%),radial-gradient(circle at 50% 46%,#e2793a,#c0451f 74%);border-radius:50% 50% 46% 46%/58% 58% 44% 44%}
.task-tree-pick .ttp.bamboo i{background:linear-gradient(92deg,#5aa155 0 22%,transparent 22% 30%,#6cb85f 30% 52%,transparent 52% 60%,#7cc267 60% 82%);border-radius:6px}
/* v35 · 三种土地=独立季节图,不再滤镜;天气强化+真实细雨 */
/* 场景岛屿层基础 */
.preview-island{position:absolute;inset:0;background-size:cover;background-position:center 46%;z-index:0}
.preview .weather-fx{z-index:1}
.preview .preview-grove{position:relative;z-index:2}
/* 土地外观卡片:岛屿季节缩略图 */
.land-grid{display:grid!important;grid-template-columns:repeat(3,1fr)!important;gap:10px!important}
.land-card{all:unset;cursor:pointer;position:relative;display:block!important;border-radius:16px;overflow:hidden;background:#fffdf5;box-shadow:0 7px 20px rgba(48,74,55,.1);border:2px solid transparent;transition:transform .2s,border-color .2s;padding:0!important}
.land-card:hover{transform:translateY(-3px)}
.land-card.selected{border-color:#4f9169!important;background:#fffdf5!important;box-shadow:0 12px 26px rgba(56,96,67,.22)}
.land-card .lc-thumb{height:70px;background-size:cover;background-position:center 42%}
.land-card b{display:block;font-size:11px;color:#2f5140;margin:8px 10px 1px}
.land-card span{display:block;font-size:9px;color:#7d8b81;margin:0 10px 10px;line-height:1.4}
.land-card .lc-check{position:absolute;top:8px;right:8px;width:22px;height:22px;border-radius:50%;background:#4f9169;color:#fff;display:grid;place-items:center;box-shadow:0 2px 6px rgba(0,0,0,.2)}
.land-card .lc-check svg{width:13px}

/* —— 天气:柔和滤镜(暖阳/细雨/晚霞),真实而不过曝 —— */
.theme-sunny .grove,.preview.theme-sunny{filter:brightness(1.05) saturate(1.08) contrast(1.01)}
.theme-rain .grove,.preview.theme-rain{filter:brightness(.96) saturate(.88) contrast(1.01)}
.theme-sunset .grove,.preview.theme-sunset{filter:saturate(1.14) brightness(1.03)}
/* 天光叠层(落在岛屿之上、树之下) */
.grove-island::after,.nb-island::after,.preview-island::after{content:'';position:absolute;inset:0;pointer-events:none;transition:background .4s;background:transparent;z-index:1}
.theme-sunny .grove-island::after,.preview.theme-sunny .preview-island::after{background:radial-gradient(130% 75% at 50% 2%,rgba(255,240,185,.42),rgba(255,244,200,.08) 45%,transparent 62%)}
.theme-sunset .grove-island::after,.preview.theme-sunset .preview-island::after{background:linear-gradient(180deg,rgba(255,190,120,.42),rgba(255,168,110,.2) 40%,rgba(240,158,120,.08) 70%,transparent 88%)}

/* —— 细雨:轻柔小雨,画面不压暗,只加冷调薄纱 + 细密雨丝 —— */
.theme-rain .grove-island::after,.preview.theme-rain .preview-island::after{
 background:linear-gradient(180deg,rgba(150,172,190,.3),rgba(176,192,206,.14) 40%,transparent 72%);}
/* 雨丝:两条细密斜线叠加,纤细且半透明,像蒙蒙细雨 */
.theme-rain .grove .weather-fx,.preview.theme-rain .weather-fx{
 z-index:3;opacity:.5;
 background:
  repeating-linear-gradient(102deg,transparent 0 9px,rgba(226,236,244,.34) 9px 9.6px,transparent 9.6px 19px),
  repeating-linear-gradient(99deg,transparent 0 15px,rgba(210,224,236,.2) 15px 15.5px,transparent 15.5px 31px);
 background-size:140px 140px,200px 200px;
 animation:rainfall .7s linear infinite,rainfall2 1.05s linear infinite;}
/* 底部极淡水汽 */
.theme-rain .grove::before,.preview.theme-rain::before{
 content:'';position:absolute;left:0;right:0;bottom:0;height:26%;z-index:4;pointer-events:none;
 background:linear-gradient(0deg,rgba(230,238,242,.32),transparent);filter:blur(1px)}
@keyframes rainfall{0%{background-position:0 0,0 0}100%{background-position:-22px 140px,0 0}}
@keyframes rainfall2{0%{background-position:0 0,0 0}100%{background-position:0 0,-18px 200px}}

/* v38 · 可拖拽树木(修复不可见) + 每目标土地天气 */
.grove-trees.free{display:block;padding:0;overflow:visible}
.tree-slot{position:absolute;transform:translate(-50%,-100%);z-index:3;cursor:grab;touch-action:none;transition:filter .2s}
.tree-slot.dragging{z-index:30;cursor:grabbing}
.tree-slot .focus-tree{position:relative;transition:none}
.tree-slot.dragging .focus-tree{filter:drop-shadow(0 14px 12px #28412e66)}
.tree-hint{position:absolute;left:100%;top:50%;transform:translateY(-50%);margin-left:8px;white-space:nowrap;z-index:40;display:flex;align-items:center;gap:4px;font-size:10px;color:#fff;background:rgba(40,55,42,.62);padding:3px 10px;border-radius:20px;pointer-events:none;backdrop-filter:blur(2px)}
.tree-hint svg{width:12px;height:12px}
/* Manage 页每块土地的地貌/天气选择器 */
.manage-row{flex-direction:column;align-items:stretch;gap:10px}
.manage-row .mr-top{display:flex;align-items:center;gap:12px}
.mr-scene{display:flex;flex-direction:column;gap:8px}
.mr-scene .sp-group{display:flex;align-items:center;gap:8px}
.mr-scene .sp-label{width:28px;flex:0 0 28px;font-size:11px;color:#7d8b81}
.mr-scene .sp-row{display:flex;gap:6px;flex:1}
.sp-chip{flex:1;padding:7px 4px;border:1px solid #d7ddd0;border-radius:11px;background:#fbfdf7;color:#5a6a5c;font-size:12px;cursor:pointer;transition:all .18s}
.sp-chip:hover{border-color:#a9c39a}
.sp-chip.on{border-color:#6f9b5e;background:#eef6e6;color:#33502f;font-weight:600;box-shadow:0 2px 8px rgba(90,140,80,.18)}

.tree-modal{text-align:center}
.tree-modal small{display:block;font-size:10px;letter-spacing:2px;color:#8aa07f;margin-bottom:4px}
.tree-modal .task-tree-pick{margin:14px 0 18px}
.tree-modal .ttp-row{display:grid;grid-template-columns:repeat(3,1fr);gap:10px}
.tree-modal .ttp{display:flex;flex-direction:column;align-items:center;gap:4px;padding:12px 4px;border:1px solid #d7ddd0;border-radius:14px;background:#fbfdf7;cursor:pointer;transition:all .18s}
.tree-modal .ttp:hover{border-color:#a9c39a}
.tree-modal .ttp.on{border-color:#6f9b5e;background:#eef6e6;box-shadow:0 2px 8px rgba(90,140,80,.18)}
.tree-modal .ttp b{font-size:12px;color:#3c5238}

.home-page::before,.project-page::before,.community::before{content:'';position:fixed;top:0;bottom:0;left:50%;transform:translateX(-50%);width:min(100%,480px);z-index:0;pointer-events:none;background-repeat:no-repeat;background-size:cover;background-position:center top}.home-page::before{background-image:linear-gradient(180deg,rgba(246,252,244,.18),rgba(222,238,218,.42)),url(data:image/jpeg;base64,)}.project-page::before{background-image:linear-gradient(180deg,rgba(255,255,255,.04),rgba(237,245,229,.10)),url(data:image/png;base64,)}.community::before{background-image:linear-gradient(180deg,rgba(248,251,241,.56),rgba(232,242,226,.78)),url(data:image/jpeg;base64,)}.community{position:relative}.community>*:not(.weather-fx):not(.modal){position:relative;z-index:1}

/* —— 成长足迹卡片(花园偏好页新增) —— */
.growth-cards{display:flex;flex-direction:column;gap:12px;margin-bottom:8px}
.grow-card{display:flex;align-items:center;gap:14px;width:100%;text-align:left;padding:16px;border-radius:20px;border:1px solid #e4ddc8;background:linear-gradient(160deg,#fffdf6,#f4efe0);box-shadow:0 6px 16px rgba(120,110,80,.10);color:#4a4633;cursor:pointer}
.grow-card>svg{width:20px;height:20px;color:#b0a682;flex:none}
.grow-ico{width:44px;height:44px;border-radius:14px;display:grid;place-items:center;flex:none;background:linear-gradient(135deg,#d9ecc6,#a9d18a);color:#3f6a2e}
.grow-ico svg{width:22px;height:22px}.grow-ico .grow-line{width:23px;height:23px}
.grow-body{flex:1;min-width:0;display:flex;flex-direction:column;gap:3px}
.grow-body b{font-size:15px;font-weight:700;color:#3d3a29;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.grow-sub{font-size:11.5px;color:#8a815f}
.grow-nums{display:flex;gap:22px;margin-top:2px}
.grow-nums>div{display:flex;flex-direction:column;gap:1px}
.grow-nums strong{font:800 22px 'Noto Serif SC';color:#3f6a2e;line-height:1}
.grow-nums em{font-style:normal;font-size:10.5px;color:#8a815f;font-weight:600}
.grow-streak{cursor:default}
.grow-cd .grow-ico{background:linear-gradient(135deg,#ffd9c2,#f4a97a);color:#9a4a1e}
.grow-cd.active{background:linear-gradient(160deg,#fff6ee,#fbe6d5);border-color:#f0cdb2}
.cd-badge{flex:none;display:flex;flex-direction:column;align-items:center;padding:6px 14px;border-radius:14px;background:linear-gradient(135deg,#f4a97a,#e07a45);color:#fff}
.cd-badge strong{font:800 22px 'Noto Serif SC';line-height:1}
.cd-badge em{font-style:normal;font-size:10px;font-weight:600;opacity:.92}
.grow-cal .grow-ico{background:linear-gradient(135deg,#c5dcf0,#8ab4e0);color:#2e5a8a}

/* —— 成长日历详情弹层(居中弹窗,固定高度,表头与日期严格对齐) —— */
.cal-detail{position:relative;width:min(100%,380px);max-height:88vh;overflow:auto;padding:24px 20px 22px;border-radius:22px;background:linear-gradient(180deg,#fffdf7,#f3efe2);box-shadow:0 18px 50px rgba(30,50,36,.34)}
.cd-sheet{position:relative;width:min(100%,480px);margin:auto;max-height:88vh;overflow:auto;padding:26px 22px 30px;border-radius:28px 28px 0 0;background:linear-gradient(180deg,#fffdf7,#f3efe2)}
.cal-detail small,.cd-sheet small{letter-spacing:.18em;font-size:10px;color:#a89c78;font-weight:700}
.cal-head{display:flex;align-items:center;justify-content:space-between;margin-top:6px}
.cal-head h2{font-size:17px;margin:0;color:#3d3a29}
.cal-nav{width:32px;height:32px;border:0;border-radius:50%;background:#eae4d6;color:#5a6a5e;display:grid;place-items:center;cursor:pointer;flex:none}
.cal-nav svg{width:17px;height:17px}
.cal-sum{font-size:12px;color:#8a815f;margin:4px 0 12px}
/* 表头与日期用同一套 7 列网格 + 同样的左右 padding,保证严格对齐 */
.cal-weekdays{display:grid;grid-template-columns:repeat(7,1fr);gap:5px;margin-bottom:6px}
.cal-weekdays span{text-align:center;font-size:11px;color:#a89c78;font-weight:600}
.cal-grid{display:grid;grid-template-columns:repeat(7,1fr);grid-template-rows:repeat(6,1fr);gap:5px;height:264px}
.cal-cell{position:relative;border-radius:9px;display:grid;place-items:center;background:#eef0e6;min-width:0}
.cal-cell.empty{background:transparent}
.cal-cell i{font-style:normal;font-size:12px;color:#6a6446;z-index:1;line-height:1}
.cal-cell b{position:absolute;bottom:5px;left:50%;transform:translateX(-50%);width:4px;height:4px;border-radius:50%;background:#3f6a2e}
.cal-cell.lvl-1{background:#dcecc9}
.cal-cell.lvl-2{background:#b6d99a}
.cal-cell.lvl-3{background:#8ac26a}
.cal-cell.lvl-4{background:#5e9a4c}
.cal-cell.lvl-3 i,.cal-cell.lvl-4 i{color:#fff}
.cal-cell.lvl-3 b,.cal-cell.lvl-4 b{background:#fff}
.cal-cell.today{outline:2px solid #e07a45;outline-offset:1px}
/* 图例:独立区块,与日历网格之间留出边距+分隔线,不会被方格覆盖 */
.cal-legend{margin-top:16px;padding-top:14px;border-top:1px solid #e7e0cd;display:flex;flex-direction:column;align-items:center;gap:6px}
.cal-legend-title{font-size:11.5px;font-weight:600;color:#6a6446}
.cal-legend-scale{display:flex;align-items:center;gap:5px;font-size:10.5px;color:#8a815f}
.cal-legend-scale .lg{width:14px;height:14px;border-radius:4px;background:#eef0e6}
.cal-legend-scale .lg.lvl-1{background:#dcecc9}
.cal-legend-scale .lg.lvl-2{background:#b6d99a}
.cal-legend-scale .lg.lvl-3{background:#8ac26a}
.cal-legend-scale .lg.lvl-4{background:#5e9a4c}
.cal-legend-note{font-size:10px;color:#a89c78}
/* —— 未来倒计时设置弹层 —— */
.cd-sheet h2{font-size:19px;margin:6px 0 4px;color:#3d3a29}
.cd-lead{font-size:12.5px;color:#8a815f;margin-bottom:16px;line-height:1.6}
.cd-form{display:flex;flex-direction:column;gap:14px}
.cd-form label{display:flex;flex-direction:column;gap:6px;font-size:12.5px;font-weight:600;color:#5a5439}
.cd-form input{border:1px solid #ddd4bd;border-radius:12px;padding:11px 13px;font-size:14px;background:#fffdf7;color:#3d3a29}
.cd-form input:focus{outline:none;border-color:#a9d18a}
.cd-btns{display:flex;gap:10px;margin-top:4px}
.cd-btns .submit{flex:1;border:0;border-radius:12px;padding:12px;font-size:14px;font-weight:700;color:#fff;background:linear-gradient(135deg,#8ac26a,#5e9a4c);cursor:pointer}
.cd-btns .submit:disabled{opacity:.5;cursor:not-allowed}
.cd-btns .ghost{border:1px solid #ddd4bd;border-radius:12px;padding:12px 18px;font-size:14px;font-weight:600;color:#9a5a3a;background:#fff;cursor:pointer}.pace-card{margin-top:10px;padding:18px;border-radius:20px;border:1px solid #e4ddc8;background:linear-gradient(160deg,#fffdf6,#f4efe0);box-shadow:0 6px 16px rgba(120,110,80,.10);color:#4a4633}.pace-head{display:flex;align-items:center;justify-content:space-between;gap:12px}.pace-title{display:flex;align-items:center;gap:12px}.pace-title .grow-ico{display:grid;place-items:center;width:40px;height:40px;border-radius:14px;background:#eef4ea;color:#2f8f5b;flex:none}.pace-title b{display:block;font-size:15px}.pace-badge{display:flex;flex-direction:column;align-items:center;line-height:1;flex:none}.pace-badge strong{font-size:24px;color:#2f8f5b}.pace-badge em{font-size:11px;color:#8a8467;font-style:normal;margin-top:2px}.pace-slider{-webkit-appearance:none;appearance:none;width:100%;height:6px;border-radius:999px;background:linear-gradient(90deg,#2f8f5b,#bfe3c9);margin:16px 0 4px;outline:none}.pace-slider::-webkit-slider-thumb{-webkit-appearance:none;appearance:none;width:22px;height:22px;border-radius:50%;background:#fff;border:3px solid #2f8f5b;box-shadow:0 2px 6px rgba(0,0,0,.18);cursor:pointer}.pace-slider::-moz-range-thumb{width:22px;height:22px;border-radius:50%;background:#fff;border:3px solid #2f8f5b;box-shadow:0 2px 6px rgba(0,0,0,.18);cursor:pointer}.pace-scale{display:flex;justify-content:space-between;font-size:11px;color:#a49c80}.pace-stages{display:grid;grid-template-columns:repeat(6,1fr);gap:6px;margin:14px 0 6px}.pace-stage{display:flex;flex-direction:column;align-items:center;gap:3px;padding:8px 2px;border-radius:12px;background:#f7f3e6;border:1px solid #ece3c9}.pace-stage b{font-size:12px;color:#4a4633}.pace-stage em{font-size:10px;color:#8a8467;font-style:normal}.pace-note{font-size:12px;color:#9a9377;line-height:1.6;margin-top:8px}